function draw(input){
const {board,width,height,params,progress}=input;
const P=VisualBook.palette;
const small=width<600;
const gap=small?28:28;
const panelW=small?width:(width-gap)/2;
const panelH=small?(height-gap)/2:height;
const positions=small?[[0,0],[0,panelH+gap]]:[[0,0],[panelW+gap,0]];
const fixed=n=>Math.abs(n)<0.0005?'0.000':n.toFixed(3);
function panel(index,fn){const [x,y]=positions[index];board.region('panel-'+index,{x,y,width:panelW,height:panelH},b=>fn(b,panelW,panelH));}
function frame(b,id,w,h,xd,yd,xlabel,ylabel){return b.axes(id,{xDomain:xd,yDomain:yd,xLabel:xlabel,yLabel:ylabel,box:[48,54,w-20,h-78],grid:false});}

const data=[[-2,-3],[-1,-1],[1,1],[2,3]];
const w=params.weight,bias=params.bias;
const predictions=data.map(([x])=>w*x+bias);
const residuals=data.map(([,y],i)=>predictions[i]-y);
const L=residuals.reduce((s,r)=>s+r*r/2,0)/data.length;
const gw=residuals.reduce((s,r,i)=>s+data[i][0]*r,0)/data.length;
const gb=residuals.reduce((s,r)=>s+r,0)/data.length;
const lossAt=u=>data.reduce((s,[x,y])=>s+(u*x+bias-y)**2/2,0)/data.length;
panel(0,(bb,W,H)=>{
 bb.text('heading','同一条直线 · 四个残差',18,22,{size:16,weight:600});
 const f=frame(bb,'data-axes',W,H,[-2.3,2.3],[-5.7,5.7],'特征 x','标签 y');
 bb.curve('prediction-line',f,[[-2.3,-2.3*w+bias],[2.3,2.3*w+bias]],{color:P.orange,width:2.5});
 data.forEach(([x,y],i)=>{
  bb.line('residual-'+i,f.x(x),f.y(y),f.x(x),f.y(predictions[i]),P.blue,2,0.55);
  bb.circle('sample-'+i,f.x(x),f.y(y),4.5,P.blue);
  bb.mark('prediction-'+i,'circle',{cx:f.x(x),cy:f.y(predictions[i]),r:3.5,fill:P.paper,stroke:P.orange,'stroke-width':1.8});
 });
 bb.text('legend','● 标签   ○ 预测   竖线：残差',18,H-28,{size:14,color:P.muted});
});
panel(1,(bb,W,H)=>{
 bb.text('heading','固定 b，只改变 w',18,22,{size:16,weight:600});
 const f=frame(bb,'loss-axes',W,H,[0,2],[0,3.2],'斜率 w','平均损失 L');
 const curve=Array.from({length:101},(_,i)=>{const u=2*i/100;return [u,lossAt(u)];});
 bb.curve('loss-curve',f,curve,{color:P.blue,width:2.5});
 bb.line('minimum-guide',f.x(1.4),f.y(0),f.x(1.4),f.y(3.2),P.faint,1);
 bb.text('minimum-label','w*=1.4',f.x(1.4),f.top+20,{size:14,anchor:'middle',color:P.muted});
 bb.line('loss-guide',f.x(w),f.y(0),f.x(w),f.y(L),P.orange,1,0.6);
 bb.circle('current-loss',f.x(w),f.y(L),5,P.orange);
 bb.text('loss-value','L = '+fixed(L),18,H-46,{size:16,color:P.ink});
 bb.text('gradient-value','∂L/∂w = '+fixed(gw),18,H-22,{size:14,color:P.muted});
});
return {data,weight:w,bias,predictions,residuals,meanHalfSquaredLoss:L,weightGradient:gw,biasGradient:gb,minimumWeightAtFixedBias:1.4,minimumLossAtFixedBias:lossAt(1.4)};
}

function draw(input){
const {board,width,height,params,progress}=input;
const P=VisualBook.palette;
const small=width<600;
const gap=small?28:28;
const panelW=small?width:(width-gap)/2;
const panelH=small?(height-gap)/2:height;
const positions=small?[[0,0],[0,panelH+gap]]:[[0,0],[panelW+gap,0]];
const fixed=n=>Math.abs(n)<0.0005?'0.000':n.toFixed(3);
function panel(index,fn){const [x,y]=positions[index];board.region('panel-'+index,{x,y,width:panelW,height:panelH},b=>fn(b,panelW,panelH));}
function frame(b,id,w,h,xd,yd,xlabel,ylabel){return b.axes(id,{xDomain:xd,yDomain:yd,xLabel:xlabel,yLabel:ylabel,box:[48,54,w-20,h-78],grid:false});}

const eta=params.eta;
const p=VisualBook.clamp(progress,0,1);
const t1=Math.min(2*p,1),t2=Math.max(2*p-1,0);
const first=[-0.5*t1,0.5*t1];
const endpoint=[first[0]-0.5*t2,first[1]-0.5*t2];
const gradients=[[-1,1],[-1,-1]],mean=[-1,0];
const updated=[1+eta,0];
const beforeLoss=0.5,afterLoss=0.5*(updated[0]-2)**2;
panel(0,(bb,W,H)=>{
 bb.text('heading','样本梯度各除以 2，再相加',18,22,{size:16,weight:600});
 const f=bb.axes('gradient-axes',{xDomain:[-1.4,0.4],yDomain:[-0.4,0.8],equalUnits:true,xLabel:'g_w',yLabel:'g_b',box:[48,54,W-24,H-78],grid:false});
 bb.line('first-guide',f.x(0),f.y(0),f.x(-0.5),f.y(0.5),P.faint,2);
 bb.line('second-guide',f.x(-0.5),f.y(0.5),f.x(-1),f.y(0),P.faint,2);
 bb.vector('first-gradient',f,[0,0],first,{color:P.blue});
 bb.vector('second-gradient',f,first,endpoint,{color:P.orange});
 bb.circle('sum-end',f.x(endpoint[0]),f.y(endpoint[1]),4,P.ink);
 bb.text('first-label','x=−1',f.x(-0.18),f.y(0.43),{size:14,color:P.blue});
 bb.text('second-label','x=+1',f.x(-1.14),f.y(0.39),{size:14,color:P.orange});
 bb.text('sum-label','平均 (−1, 0)',f.x(-0.7),f.y(-0.2),{size:14,anchor:'middle'});
 bb.text('cancel-label','g_b 相消；g_w 同向',18,H-28,{size:14,color:P.muted});
});
panel(1,(bb,W,H)=>{
 bb.text('heading','按 −ηg 做一次更新',18,22,{size:16,weight:600});
 const f=frame(bb,'update-axes',W,H,[-1.2,1.2],[-4.4,4.4],'特征 x','标签 y');
 bb.curve('before',f,[[-1.2,-1.2],[1.2,1.2]],{color:P.muted,width:1.5});
 bb.curve('after',f,[[-1.2,-1.2*updated[0]],[1.2,1.2*updated[0]]],{color:P.orange,width:2.5});
 [[-1,-2],[1,2]].forEach(([x,y],i)=>bb.circle('target-'+i,f.x(x),f.y(y),4.5,P.blue));
 bb.text('parameters','w：1 → '+fixed(updated[0])+'   b：0 → 0',18,H-46,{size:14});
 bb.text('loss-change','L：0.500 → '+fixed(afterLoss),18,H-22,{size:16,color:P.orange});
});
return {batch:[[-1,-2],[1,2]],initialParameters:[1,0],residuals:[1,-1],sampleGradients:gradients,averageGradient:mean,eta,update:[eta,0],updatedParameters:updated,beforeLoss,afterLoss,constructionProgress:p,visibleAverage:endpoint,convention:'左图连续构造两项平均梯度；右图始终为一次离散更新的最终结果。'};
}

function draw(input){
const {board,width,height,params,progress}=input;
const P=VisualBook.palette;
const small=width<600;
const gap=small?28:28;
const panelW=small?width:(width-gap)/2;
const panelH=small?(height-gap)/2:height;
const positions=small?[[0,0],[0,panelH+gap]]:[[0,0],[panelW+gap,0]];
const fixed=n=>Math.abs(n)<0.0005?'0.000':n.toFixed(3);
function panel(index,fn){const [x,y]=positions[index];board.region('panel-'+index,{x,y,width:panelW,height:panelH},b=>fn(b,panelW,panelH));}
function frame(b,id,w,h,xd,yd,xlabel,ylabel){return b.axes(id,{xDomain:xd,yDomain:yd,xLabel:xlabel,yLabel:ylabel,box:[48,54,w-20,h-78],grid:false});}

const e=params.residual,sigma=params.sigma;
const normal=r=>Math.exp(-r*r/(2*sigma*sigma))/(Math.sqrt(2*Math.PI)*sigma);
const extra=r=>r*r/(2*sigma*sigma);
const half=r=>r*r/2;
const xs=Array.from({length:151},(_,i)=>-2.6+5.2*i/150);
panel(0,(bb,W,H)=>{
 bb.text('heading','高斯噪声：大残差更少见',18,22,{size:16,weight:600});
 const f=frame(bb,'density-axes',W,H,[-2.6,2.6],[0,0.75],'残差 e','密度 p(e)');
 bb.curve('density',f,xs.map(x=>[x,normal(x)]),{color:P.blue,width:2.5});
 bb.line('residual-guide',f.x(e),f.y(0),f.x(e),f.y(normal(e)),P.orange,1.5);
 bb.circle('density-point',f.x(e),f.y(normal(e)),5,P.orange);
 bb.text('density-readout','p(e) = '+fixed(normal(e)),18,H-46,{size:16});
 bb.text('density-note','密度，不是单点概率',18,H-22,{size:14,color:P.muted});
});
panel(1,(bb,W,H)=>{
 bb.text('heading','取负对数后，留下平方项',18,22,{size:16,weight:600});
 const f=frame(bb,'penalty-axes',W,H,[-2.6,2.6],[0,9.6],'残差 e','损失项');
 bb.curve('squared-loss',f,xs.map(x=>[x,half(x)]),{color:P.blue,width:2});
 bb.curve('excess-nll',f,xs.map(x=>[x,extra(x)]),{color:P.orange,width:2.5});
 bb.line('nll-guide',f.x(e),f.y(half(e)),f.x(e),f.y(extra(e)),P.muted,1.3,0.7);
 bb.circle('half-point',f.x(e),f.y(half(e)),4,P.blue);
 bb.circle('nll-point',f.x(e),f.y(extra(e)),5,P.orange);
 bb.text('minimum','共同最低点：e=0',f.x(0),f.top+24,{size:14,anchor:'middle',color:P.muted});
 bb.text('half-readout','½e² = '+fixed(half(e)),18,H-46,{size:14,color:P.blue});
 bb.text('nll-readout','½e² / σ² = '+fixed(extra(e)),18,H-22,{size:14,color:P.orange});
});
return {residual:e,sigma,variance:sigma*sigma,density:normal(e),halfSquaredLoss:half(e),excessNegativeLogLikelihood:extra(e),constant:Math.log(Math.sqrt(2*Math.PI)*sigma),negativeLogLikelihood:-Math.log(normal(e)),minimumResidual:0,convention:'固定正sigma、独立同方差高斯噪声；右图去除与模型参数无关的对数常数。'};
}
